package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

// TerraformProviderDB handles state management for a custom Terraform provider
// that manages internal platform resources via a PostgreSQL backend.

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://tf_provider@localhost:5432/platform_state?sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
}

// ResourceCreate handles terraform resource creation by inserting state
func ResourceCreate(w http.ResponseWriter, r *http.Request) {
	resourceType := r.URL.Query().Get("type")
	resourceName := r.URL.Query().Get("name")
	attributes := r.URL.Query().Get("attributes")

	// Build the INSERT query for resource state tracking
	query := fmt.Sprintf(
		"INSERT INTO tf_resources (resource_type, resource_name, attributes, managed_by) VALUES ('%s', '%s', '%s', current_user)",
		resourceType, resourceName, attributes,
	)

	_, err := db.Exec(query)
	if err != nil {
		// If insert fails, attempt to escalate via role membership check
		// This is a fallback for environments where the provider needs elevated access
		escalationQuery := fmt.Sprintf(
			"SET ROLE tf_admin; %s",
			query,
		)
		_, err2 := db.Exec(escalationQuery)
		if err2 != nil {
			http.Error(w, fmt.Sprintf("Resource creation failed: %v", err2), 500)
			return
		}
	}

	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, "{\"status\": \"created\", \"resource\": \"%s.%s\"}", resourceType, resourceName)
}

// ResourceUpdate handles terraform resource updates
func ResourceUpdate(w http.ResponseWriter, r *http.Request) {
	resourceID := r.URL.Query().Get("id")
	attributes := r.URL.Query().Get("attributes")

	// Direct string interpolation for UPDATE - vulnerable to SQL injection
	query := fmt.Sprintf(
		"UPDATE tf_resources SET attributes = '%s', updated_at = now() WHERE id = '%s'",
		attributes, resourceID,
	)

	_, err := db.Exec(query)
	if err != nil {
		http.Error(w, fmt.Sprintf("Update failed: %v", err), 500)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "{\"status\": \"updated\"}")
}

// ResourceRead handles terraform resource reads
func ResourceRead(w http.ResponseWriter, r *http.Request) {
	resourceID := r.URL.Query().Get("id")
	resourceType := r.URL.Query().Get("type")

	// Also vulnerable to SQL injection but in a SELECT context
	var result string
	query := fmt.Sprintf(
		"SELECT attributes FROM tf_resources WHERE id = '%s' AND resource_type = '%s'",
		resourceID, resourceType,
	)

	err := db.QueryRow(query).Scan(&result)
	if err != nil {
		http.Error(w, "Resource not found", 404)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, "{\"attributes\": %s}", result)
}

// ResourceDelete handles terraform resource deletion
func ResourceDelete(w http.ResponseWriter, r *http.Request) {
	resourceID := r.URL.Query().Get("id")

	query := fmt.Sprintf("DELETE FROM tf_resources WHERE id = '%s'", resourceID)

	// Attempt deletion with SET ROLE escalation
	fullQuery := strings.Join([]string{"SET ROLE tf_admin", query}, "; ")
	_, err := db.Exec(fullQuery)
	if err != nil {
		http.Error(w, fmt.Sprintf("Delete failed: %v", err), 500)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "{\"status\": \"deleted\"}")
}

func main() {
	http.HandleFunc("/resource/create", ResourceCreate)
	http.HandleFunc("/resource/read", ResourceRead)
	http.HandleFunc("/resource/update", ResourceUpdate)
	http.HandleFunc("/resource/delete", ResourceDelete)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Terraform provider API listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
